head.b:skin:
/* ===== Anima Play — Netflix Style ===== */
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a0a;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow-x:hidden}
a{color:#e50914;text-decoration:none}
img{display:block;max-width:100%}
.hidden{display:none!important}

/* Header */
.ap-header{display:flex;align-items:center;gap:24px;flex-wrap:wrap;padding:14px 32px;background:rgba(10,10,10,.95);border-bottom:1px solid #1a1a1a;position:sticky;top:0;z-index:100;backdrop-filter:blur(10px)}
.ap-logo a{font-size:28px;font-weight:800;color:#e50914;text-transform:uppercase;letter-spacing:1px}
.ap-nav{display:flex;gap:16px;flex-wrap:wrap}
.ap-nav a{color:#ccc;font-size:14px;font-weight:600;transition:color .2s}
.ap-nav a:hover{color:#e50914}
.ap-search{margin-left:auto;display:flex;gap:8px}
.ap-search input{background:#15191d;border:1px solid #2a2a2a;color:#fff;border-radius:8px;padding:8px 12px;font-size:13px;width:200px}
.ap-search button{background:#e50914;border:none;color:#fff;border-radius:8px;padding:8px 16px;font-size:13px;font-weight:700;cursor:pointer}

/* Netflix Rows */
.ap-content{max-width:1320px;margin:0 auto;padding:24px 32px}
.ap-row{margin-bottom:32px}
.ap-row-header{display:flex;align-items:baseline;gap:12px;margin-bottom:12px}
.ap-row-title{font-size:20px;font-weight:700;color:#fff}
.ap-row-sub{font-size:12px;color:#888}
.ap-row-scroll{display:flex;gap:10px;overflow-x:auto;scroll-behavior:smooth;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding-bottom:8px}
.ap-row-scroll::-webkit-scrollbar{display:none}

/* Cards */
.ap-card{flex:0 0 180px;border-radius:8px;overflow:hidden;background:#141414;border:2px solid transparent;transition:all .25s ease;cursor:pointer;position:relative}
.ap-card:hover{border-color:#e50914;transform:scale(1.05);z-index:2}
.ap-card-img{width:100%;aspect-ratio:2/3;object-fit:cover;background:#1a1a1a}
.ap-card-badge{position:absolute;top:6px;left:6px;background:#e50914;color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:4px;text-transform:uppercase}
.ap-card-body{padding:8px 10px}
.ap-card-title{font-size:13px;font-weight:700;color:#fff;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ap-card-meta{font-size:11px;color:#888;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ap-card-genres{display:flex;gap:4px;margin-top:4px;flex-wrap:wrap}
.ap-card-genres span{font-size:9px;color:#aaa;background:rgba(255,255,255,.08);padding:1px 5px;border-radius:3px}

/* Wide card (horizontal) for "top" rows */
.ap-card-wide{flex:0 0 280px;display:flex;flex-direction:row}
.ap-card-wide .ap-card-img{width:120px;height:90px;aspect-ratio:auto;flex-shrink:0}
.ap-card-wide .ap-card-body{padding:10px;display:flex;flex-direction:column;justify-content:center}

/* Scroll buttons */
.ap-row-wrap{position:relative}
.ap-scroll-btn{position:absolute;top:50%;transform:translateY(-50%);width:36px;height:36px;border-radius:50%;background:rgba(10,10,10,.85);border:1px solid #333;color:#fff;font-size:18px;cursor:pointer;z-index:3;display:flex;align-items:center;justify-content:center;transition:all .2s;opacity:0}
.ap-row-wrap:hover .ap-scroll-btn{opacity:1}
.ap-scroll-btn:hover{background:#e50914;border-color:#e50914}
.ap-scroll-left{left:-18px}
.ap-scroll-right{right:-18px}

/* Hero (post page) */
.ap-hero{position:relative;border-radius:12px;overflow:hidden;margin-bottom:16px;min-height:260px;background:#1a1a1a}
.ap-hero img{width:100%;max-height:400px;object-fit:cover}
.ap-hero-overlay{position:absolute;bottom:0;left:0;right:0;padding:60px 24px 20px;background:linear-gradient(transparent,#0a0a0a)}
.ap-hero-overlay h1{font-size:28px;font-weight:800}
.ap-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.ap-meta span{background:rgba(255,255,255,.15);padding:3px 10px;border-radius:12px;font-size:12px;color:#ccc}

/* Post page */
.ap-post{max-width:900px;margin:0 auto;padding:20px}
.post-synopsis{color:#aaa;font-size:14px;line-height:1.7;margin-bottom:6px}
.video-player{position:relative;width:100%;padding-top:56.25%;background:#000;border-radius:12px;overflow:hidden;margin-bottom:12px}
.video-player iframe,.video-player video{position:absolute;top:0;left:0;width:100%;height:100%;border:none}
.server-tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}
.server-tabs button{background:#15191d;color:#ccc;border:1px solid #2a2a2a;padding:7px 14px;border-radius:999px;font-size:12px;font-weight:700;cursor:pointer}
.server-tabs button.active{background:#e50914;border-color:#e50914;color:#fff}
.ep-nav{display:flex;gap:10px;align-items:center;margin-bottom:24px;flex-wrap:wrap}
.ep-nav button{background:#15191d;color:#fff;border:1px solid #2a2a2a;padding:10px 16px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer}
.ep-nav button:hover:not(:disabled){border-color:#e50914;color:#e50914}
.ep-nav button:disabled{opacity:.35;cursor:not-allowed}
.ep-nav button.primary{background:#e50914;border-color:#e50914}
.ep-nav #epLabel{font-size:13px;color:#888}
.section-label{font-size:13px;color:#e50914;text-transform:uppercase;letter-spacing:1px;margin:18px 0 12px;font-weight:700}
.episode-list{display:flex;flex-direction:column;gap:8px}
.episode-item{display:flex;gap:12px;align-items:center;background:#141414;border:1px solid #222;border-radius:10px;padding:10px 12px;text-decoration:none;color:#fff;cursor:pointer;transition:border-color .2s}
.episode-item:hover{border-color:#e50914}
.episode-item.active{border-color:#e50914}
.episode-item .ep-thumb{width:96px;height:54px;object-fit:cover;border-radius:6px;background:#1a1a1a;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:10px;color:#888}
.episode-item .episode-info{flex:1;min-width:0}
.episode-item .ep-title{font-size:14px;font-weight:700}
.episode-item .ep-meta{font-size:12px;color:#888}
.episode-item .btn-play{background:none;border:2px solid #555;color:#fff;border-radius:50%;width:36px;height:36px;font-size:13px;cursor:pointer;flex-shrink:0}
.episode-item:hover .btn-play{border-color:#e50914;color:#e50914}
.ap-watch-main{display:inline-block;background:#e50914;color:#fff;border-radius:8px;padding:10px 18px;font-weight:700;text-decoration:none;margin-top:14px}

/* Footer */
.ap-footer{text-align:center;padding:32px;color:#555;font-size:12px;border-top:1px solid #1a1a1a;margin-top:20px}

@media(max-width:768px){
  .ap-header{padding:12px 16px;gap:12px}
  .ap-content{padding:16px}
  .ap-card{flex:0 0 140px}
  .ap-scroll-btn{display:none}
  .ap-search{margin-left:0;width:100%}
  .ap-search input{flex:1}
}

body.script:
//
var AP = (function () {
  var LABELS = ['Ação','Aventura','Comédia','Drama','Fantasia','Terror','Romance','Suspense','Ficção','Esporte','Dublado','Filme','Clássico'];
  var POSTS = [];

  function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

  function fetchPosts(pageToken, acc) {
    acc = acc || [];
    var url = '/feeds/posts/default?alt=json&max-results=50' + (pageToken ? '&start-index=' + pageToken : '');
    return fetch(url).then(function (r) { return r.json(); }).then(function (j) {
      var entries = (j.feed && j.feed.entry) || [];
      entries.forEach(function (e) {
        var title = (e.title && e.title.$t) || '';
        var href = '#';
        (e.link || []).forEach(function (l) { if (l.rel === 'alternate') href = l.href; });
        var img = '';
        if (e.media$thumbnail && e.media$thumbnail.url) img = String(e.media$thumbnail.url).replace(/\/s72(-c)?\//, '/s400/');
        if (!img && e.content && e.content.$t) {
          var m = String(e.content.$t).match(/<img[^>]+src=["']([^"']+)["']/i);
          if (m) img = m[1];
        }
        var labels = [];
        (e.category || []).forEach(function (c) { if (c.term) labels.push(c.term); });
        var body = '';
        if (e.content && e.content.$t) {
          var tmp = document.createElement('div');
          tmp.innerHTML = e.content.$t;
          var dataEl = tmp.querySelector('#anima-data');
          if (dataEl) {
            try {
              var d = JSON.parse(dataEl.textContent);
              if (d.synopsis) body = d.synopsis;
              if (d.cover && !img) img = d.cover;
              if (d.episodes) {
                var epCount = d.episodes.length;
                var srvCount = 0;
                d.episodes.forEach(function (ep) { if (ep.videos) srvCount += ep.videos.length; });
                if (epCount) body = epCount + ' episódios · ' + srvCount + ' vídeos';
              }
            } catch (ex) {}
          }
          if (!body) {
            body = (tmp.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 120);
          }
        }
        POSTS.push({ title: title, href: href, img: img, labels: labels, body: body });
      });
      var total = j.feed && j.feed.openSearch$totalFields && parseInt(j.feed.openSearch$totalFields.$t, 10);
      var next = acc.length + entries.length;
      if (next < total && entries.length) {
        return fetchPosts(next + 1, acc.concat(entries));
      }
      return acc.concat(entries);
    });
  }

  function cardHTML(p, wide) {
    var cls = wide ? 'ap-card ap-card-wide' : 'ap-card';
    var h = '<a class="' + cls + '" href="' + esc(p.href) + '">';
    h += '<img class="ap-card-img" src="' + esc(p.img || 'https://via.placeholder.com/180x270/141414/333?text=Sem+Capa') + '" alt="' + esc(p.title) + '" loading="lazy"/>';
    if (p.isNew) h += '<div class="ap-card-badge">NOVO</div>';
    h += '<div class="ap-card-body">';
    h += '<div class="ap-card-title">' + esc(p.title) + '</div>';
    if (p.body) h += '<div class="ap-card-meta">' + esc(p.body) + '</div>';
    if (p.labels && p.labels.length && !wide) {
      h += '<div class="ap-card-genres">';
      p.labels.slice(0, 3).forEach(function (l) { h += '<span>' + esc(l) + '</span>'; });
      h += '</div>';
    }
    h += '</div></a>';
    return h;
  }

  function rowHTML(title, sub, posts, wide) {
    if (!posts.length) return '';
    var h = '<div class="ap-row-wrap ap-row">';
    h += '<div class="ap-row-header"><span class="ap-row-title">' + esc(title) + '</span>';
    if (sub) h += '<span class="ap-row-sub">' + esc(sub) + '</span>';
    h += '</div>';
    h += '<div class="ap-row-scroll">';
    posts.forEach(function (p) { h += cardHTML(p, wide); });
    h += '</div>';
    h += '<button class="ap-scroll-btn ap-scroll-left" onclick="this.nextElementSibling.scrollBy({left:-600,behavior:\'smooth\'})">‹</button>';
    h += '<button class="ap-scroll-btn ap-scroll-right" onclick="this.previousElementSibling.scrollBy({left:600,behavior:\'smooth\'})">›</button>';
    h += '</div>';
    return h;
  }

  function getRecent(n) {
    return POSTS.slice(0, n || 10);
  }

  function getByLabel(label) {
    return POSTS.filter(function (p) { return p.labels && p.labels.indexOf(label) >= 0; });
  }

  function markNew(posts, n) {
    var out = posts.slice();
    for (var i = 0; i < n && i < out.length; i++) out[i].isNew = true;
    return out;
  }

  function renderHome() {
    var el = document.getElementById('apRows');
    if (!el) return;
    if (!POSTS.length) { el.innerHTML = '<p style="text-align:center;color:#888;padding:60px 0">Nenhum post encontrado</p>'; return; }
    var h = '';
    h += rowHTML('Últimos Episódios', 'Em alta no site', markNew(getRecent(10)), false);
    LABELS.forEach(function (l) {
      var posts = getByLabel(l);
      if (posts.length >= 2) h += rowHTML(l, posts.length + ' títulos', posts, false);
    });
    el.innerHTML = h;
    var total = document.getElementById('apTotal');
    if (total && typeof ViewCounter !== 'undefined') {
      try { ViewCounter.getSiteViews().then(function (v) { total.textContent = v; }); } catch (e) {}
    }
  }

  function renderPost() {
    var el = document.getElementById('apContent');
    if (!el) return;
    var dataEl = document.getElementById('anima-data');
    if (!dataEl) { el.innerHTML = '<p style="text-align:center;color:#888;padding:60px 0">Post sem dados</p>'; return; }
    var d;
    try { d = JSON.parse(dataEl.textContent); } catch (e) { el.innerHTML = '<p style="text-align:center;color:#888;padding:60px 0">Erro nos dados</p>'; return; }
    el.innerHTML = '<div class="ap-post" id="apPost"></div>';
    var post = document.getElementById('apPost');
    if (!d.episodes || !d.episodes.length) { post.innerHTML = '<p>Sem episódios</p>'; return; }
    var cur = 0;
    var srv = 0;
    function curUrl() {
      var ep = d.episodes[cur];
      var v = (ep && ep.videos && ep.videos[srv]) || (ep && ep.videos && ep.videos[0]);
      return (v && v.url) || d.defaultVideo || '';
    }
    function isDirect(s) { return /\.(mp4|webm)(\?|#|$)/i.test(s || ''); }
    function paintPlayer() {
      var box = document.getElementById('vp');
      if (!box) return;
      var src = curUrl();
      if (!src) { box.innerHTML = '<div style="padding:40px;text-align:center;color:#666">Nenhum vídeo</div>'; return; }
      if (isDirect(src)) box.innerHTML = '<video controls preload="none" src="' + esc(src) + '"></video>';
      else box.innerHTML = '<iframe src="' + esc(src) + '" allowfullscreen="true" loading="lazy"></iframe>';
    }
    function render() {
      var pills = (d.genres || []).map(function (g) { return '<span>' + esc(g) + '</span>'; }).join('');
      var h = '<div class="ap-hero">';
      if (d.cover) h += '<img src="' + esc(d.cover) + '" alt="' + esc(d.title) + '"/>';
      h += '<div class="ap-hero-overlay"><h1>' + esc(d.title) + '</h1><div class="ap-meta">' + pills + '</div></div></div>';
      if (d.synopsis) h += '<p class="post-synopsis">' + esc(d.synopsis) + '</p>';
      h += '<div class="section-label">Assistir</div>';
      h += '<div class="video-player" id="vp"></div>';
      var vids = (d.episodes[cur] && d.episodes[cur].videos) || [];
      if (vids.length > 1) {
        h += '<div class="server-tabs" id="svTabs">';
        vids.forEach(function (v, j) {
          h += '<button class="' + (j === srv ? 'active' : '') + '" data-srv="' + j + '">' + esc(v.name || ('Servidor ' + (j + 1))) + '</button>';
        });
        h += '</div>';
      }
      h += '<div class="ep-nav">';
      h += '<button onclick="location.href=\'/\'">← Início</button>';
      h += '<button id="btnPrev"' + (cur <= 0 ? ' disabled' : '') + '>← Anterior</button>';
      h += '<span id="epLabel">' + esc(d.episodes[cur].title || ('Episódio ' + (cur + 1))) + ' · ' + (cur + 1) + '/' + d.episodes.length + '</span>';
      h += '<button id="btnNext" class="primary"' + (cur >= d.episodes.length - 1 ? ' disabled' : '') + '>Próximo →</button>';
      h += '</div>';
      h += '<div class="section-label">Episódios</div>';
      h += '<div class="episode-list">';
      d.episodes.forEach(function (ep, i) {
        var n = (ep.videos || []).length;
        var label = n > 1 ? (n + ' servidores') : 'Toque para assistir';
        h += '<a class="episode-item' + (i === cur ? ' active' : '') + '" data-ep="' + i + '">';
        h += '<div class="ep-thumb">EP ' + String(i + 1).padStart(2, '0') + '</div>';
        h += '<div class="episode-info"><div class="ep-title">' + esc(ep.title || ('Episódio ' + (i + 1))) + '</div>';
        h += '<div class="ep-meta">' + esc(label) + '</div></div>';
        h += '<button class="btn-play">▶</button></a>';
      });
      h += '</div>';
      h += '<a class="ap-watch-main" href="https://animaplays.github.io/posts/' + esc(d.slug) + '.html">Assistir no Anima Play</a>';
      post.innerHTML = h;
      paintPlayer();
      post.querySelectorAll('[data-srv]').forEach(function (btn) {
        btn.addEventListener('click', function () {
          srv = parseInt(this.getAttribute('data-srv'), 10);
          paintPlayer();
          post.querySelectorAll('[data-srv]').forEach(function (b) { b.classList.remove('active'); });
          btn.classList.add('active');
        });
      });
      post.querySelectorAll('[data-ep]').forEach(function (item) {
        item.addEventListener('click', function (e) {
          e.preventDefault();
          cur = parseInt(this.getAttribute('data-ep'), 10);
          srv = 0;
          render();
          document.getElementById('vp').scrollIntoView({ behavior: 'smooth', block: 'center' });
        });
      });
      var pv = document.getElementById('btnPrev');
      var nx = document.getElementById('btnNext');
      if (pv) pv.addEventListener('click', function () { if (cur > 0) { cur--; srv = 0; render(); } });
      if (nx) nx.addEventListener('click', function () { if (cur < d.episodes.length - 1) { cur++; srv = 0; render(); } });
      try {
        var u = new URL(window.location.href);
        var ep = parseInt(u.searchParams.get('ep') || '1', 10);
        if (ep >= 1 && ep <= d.episodes.length) { cur = ep - 1; render(); }
      } catch (e) {}
      if (typeof ViewCounter !== 'undefined' && d.slug) {
        try { ViewCounter.increment(d.slug).then(function (v) {
          var el2 = document.getElementById('apViews');
          if (el2) el2.textContent = v + ' visualizações';
        }); } catch (e) {}
      }
    }
    render();
  }

  function boot() {
    var dataEl = document.getElementById('anima-data');
    var isPost = dataEl && dataEl.textContent.trim().indexOf('{') === 0;
    if (isPost) {
      renderPost();
    } else {
      fetchPosts(1).then(function () { renderHome(); }).catch(function () {
        document.getElementById('apRows').innerHTML = '<p style="text-align:center;color:#888;padding:60px 0">Erro ao carregar</p>';
      });
    }
    var q = document.getElementById('apQ'), go = document.getElementById('apGo');
    function doSearch() { var v = q ? q.value.trim() : ''; if (v) location.href = '/search?q=' + encodeURIComponent(v); }
    if (go) go.addEventListener('click', doSearch);
    if (q) q.addEventListener('keydown', function (e) { if (e.key === 'Enter') doSearch(); });
  }

  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('DOMContentLoaded', boot);
  }
  return { boot: boot };
})();
//
